  3 | int binarySearch(int arr[], int n, int x) {
  4 |     int low = 0, high = n ;
  5 | 
  6 |     while (low <= high) {
  7 |         int mid = low + (high - low) / 2;
  8 | 
  9 |         if (arr[mid] == x)
 10 |             return mid;
 11 |         else if (arr[mid] < x)
 12 |             low = mid + 1;
 13 |         else
 14 |             high = mid - 1;
 15 |     }
 16 | 
 17 |     return -1;
 18 | }
